mas":-1}},"esperado":true,"casuistica":"BAJO_EL_LIMITE"},{"entrada":{"as_clarity_visual_states":true,"as_node_state_wrong":false,"as_completed_before_condition":false,"as_future_disabled":false,"as_future_not_focusable":false,"as_hover_changes_state":false,"as_focus_changes_state":false,"as_color_literal_used":false,"as_state_token_mapping_wrong":false,"as_decorative_path_exposed":false,"as_reward_wrong":false,"as_focus_outline_px":{"param":"UX.CLARITY_FOCUS_OUTLINE_PX","mas":0},"as_focus_offset_px":{"param":"UX.CLARITY_FOCUS_OFFSET_PX","mas":0}},"esperado":false,"casuistica":"EN_EL_LIMITE"},{"entrada":{"as_clarity_visual_states":true,"as_node_state_wrong":false,"as_completed_before_condition":false,"as_future_disabled":false,"as_future_not_focusable":false,"as_hover_changes_state":false,"as_focus_changes_state":false,"as_color_literal_used":false,"as_state_token_mapping_wrong":false,"as_decorative_path_exposed":false,"as_reward_wrong":false,"as_focus_outline_px":{"param":"UX.CLARITY_FOCUS_OUTLINE_PX","mas":0},"as_focus_offset_px":{"param":"UX.CLARITY_FOCUS_OFFSET_PX","mas":1}},"esperado":true,"casuistica":"SOBRE_EL_LIMITE"},{"entrada":{"as_clarity_visual_states":false,"as_node_state_wrong":true,"as_completed_before_condition":false,"as_future_disabled":false,"as_future_not_focusable":false,"as_hover_changes_state":false,"as_focus_changes_state":false,"as_color_literal_used":false,"as_state_token_mapping_wrong":false,"as_decorative_path_exposed":false,"as_reward_wrong":false,"as_focus_outline_px":{"param":"UX.CLARITY_FOCUS_OUTLINE_PX","mas":0},"as_focus_offset_px":{"param":"UX.CLARITY_FOCUS_OFFSET_PX","mas":0}},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]},"hash_paquete":"029fef8b2c9cf930f94a5bd303997b5e4ad159469a4903a89132864c5b714024","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 IF lf_ops.nucleo_param_valor_v1('AUTH.DNI_FORMAT_LENGTH') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUTH' AND config_key='DNI_FORMAT_LENGTH' AND hecho='as_dni_length') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT AUTH.DNI_FORMAT_LENGTH'; END IF;
 IF lf_ops.nucleo_param_valor_v1('AUTH.OTP_ORDINARY_RESEND_TIMER_SECONDS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUTH' AND config_key='OTP_ORDINARY_RESEND_TIMER_SECONDS' AND hecho='as_otp_resend_seconds') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT AUTH.OTP_ORDINARY_RESEND_TIMER_SECONDS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('AUTH.OTP_UI_SLOT_COUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='AUTH' AND config_key='OTP_UI_SLOT_COUNT' AND hecho='as_otp_slots') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT AUTH.OTP_UI_SLOT_COUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CTA_TOUCH_TARGET_MIN_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CTA_TOUCH_TARGET_MIN_PX' AND hecho='as_cta_min_dimension_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CTA_TOUCH_TARGET_MIN_PX'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.DISPLAY_WHOLE_AMOUNT_DECIMALS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='DISPLAY_WHOLE_AMOUNT_DECIMALS' AND hecho='as_whole_amount_decimals') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT CLIENT.DISPLAY_WHOLE_AMOUNT_DECIMALS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('CLIENT.DISPLAY_INSTALLMENT_DECIMALS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='CLIENT' AND config_key='DISPLAY_INSTALLMENT_DECIMALS' AND hecho='as_installment_decimals') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT CLIENT.DISPLAY_INSTALLMENT_DECIMALS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.HOME_VARIANT_MAX_SKELETON_SECONDS') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='HOME_VARIANT_MAX_SKELETON_SECONDS' AND hecho='as_home_wait_seconds') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.HOME_VARIANT_MAX_SKELETON_SECONDS'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_NODE_MIN_TEXT_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_NODE_MIN_TEXT_PX' AND hecho='as_clarity_min_text_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_NODE_MIN_TEXT_PX'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_NODE_COUNT') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_NODE_COUNT' AND hecho='as_clarity_node_count') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_NODE_COUNT'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_FOCUS_OUTLINE_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_FOCUS_OUTLINE_PX' AND hecho='as_focus_outline_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_FOCUS_OUTLINE_PX'; END IF;
 IF lf_ops.nucleo_param_valor_v1('UX.CLARITY_FOCUS_OFFSET_PX') IS NULL OR NOT EXISTS (SELECT 1 FROM lf_ops.nucleo_parametros WHERE scope='UX' AND config_key='CLARITY_FOCUS_OFFSET_PX' AND hecho='as_focus_offset_px') THEN RAISE EXCEPTION 'S22AS_PARAM_PREFLIGHT UX.CLARITY_FOCUS_OFFSET_PX'; END IF;
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT count(DISTINCT (cv.coverage->>'legacy_id')::bigint) INTO expected_delta FROM jsonb_array_elements(packs) AS pk(package) CROSS JOIN LATERAL jsonb_array_elements(pk.package->'coberturas') AS cv(coverage) WHERE cv.coverage->>'estado_cobertura'='REEMPLAZADA' AND NOT EXISTS (SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada AS existing_cov WHERE existing_cov.legacy_id=(cv.coverage->>'legacy_id')::bigint AND existing_cov.estado_cobertura='REEMPLAZADA');
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','Claude 2026-11-26 07:20 Lima: Revisado conforme; 13 paquetes, 44/49/85/163 reemplazadas y siete legadas parciales con residual; juicio V3 independiente');
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22AS_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22AS_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22AS_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>jsonb_array_length(packs) OR vectors<>(SELECT coalesce(sum(jsonb_array_length(value->'paquete'->'pruebas')),0) FROM jsonb_array_elements(packs)) THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22AS_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22AS_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-26 07:02 Lima'),h,'GPT / Claude S22-AS independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22AS_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>(SELECT coalesce(sum(jsonb_array_length(value->'coberturas')),0) FROM jsonb_array_elements(packs)) OR after_replaced<>before_replaced+expected_delta) THEN RAISE EXCEPTION 'S22AS_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22AS_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22AS_PASS JUICIOS=% AUTO=% VECTORES=% links=% replaced=% DPIG03=0',n,n,vectors,links,after_replaced;
END $as$;
COMMIT;
